export function Callback({
  parentName = "{{parentName}}",
  childName = "{{childName}}",
  callbackName = "{{callbackName}}",
  status = "{{status}}",
}) {
  const fired = status === "fired";
  return (
    <div role="img" aria-label={`${parentName} passes ${callbackName} to ${childName}, call state ${status}`}
      style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 300, boxSizing: "border-box", display: "flex", alignItems: "center", gap: 10 }}>
      <div style={{ flex: 1, padding: 14, borderRadius: 8, background: "#24143010", textAlign: "center", fontWeight: 600, boxSizing: "border-box" }}>{parentName}</div>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", fontSize: 10, color: "#24143099", flexShrink: 0 }}>
        <span style={{ fontFamily: "ui-monospace, monospace", marginBottom: 2 }}>{callbackName}={"{handle}"}</span>
        <span aria-hidden="true" style={{ fontSize: 16, color: fired ? "#241430" : "#24143060" }}>&rarr;</span>
      </div>
      <div style={{ flex: 1, padding: 14, borderRadius: 8, textAlign: "center", fontWeight: 600, boxSizing: "border-box", background: fired ? "#A8E6C1" : "#24143010" }}>
        {childName}
        {fired && <span style={{ display: "block", marginTop: 4, fontSize: 10, fontWeight: 400, color: "#24143099" }}>called {callbackName}()</span>}
      </div>
    </div>
  );
}
